  $clean=[];foreach(['id'=>96,'name'=>300,'type'=>20,'equipment'=>300,'source'=>600,'node_id'=>60,'node_name'=>180,'notes'=>1200] as $f=>$max)$clean[$f]=textField($op,$f,$max,in_array($f,['id','name','type'],true));
  foreach(['seconds'=>86400,'estimated_seconds'=>86400,'setup_minutes'=>1440,'batch'=>100000,'grade'=>6] as $f=>$max)$clean[$f]=numberField($op,$f,in_array($f,['setup_minutes'],true)?0:1,$max,true);
