 }else{
  $orders=rows('SELECT * FROM orders WHERE company_id=? ORDER BY deadline,id',[$c['id']]);foreach($orders as &$o){$o['route']=decode($o['route']);$o['expenses']=decode($o['expenses']);}unset($o);
  $period=analyticsPeriod($input,$c['passport']['timezone']);if(!empty($input['deadline_filter']))$orders=array_values(array_filter($orders,fn($o)=>$o['deadline']>=$period['from']&&$o['deadline']<=$period['to']));
  if(in_array($kind,['statistics','all'],true)){
   $insights=null;if(!empty($input['analysis_job_id'])){$job=one("SELECT * FROM assistant_jobs WHERE id=? AND company_id=? AND actor_id=? AND kind='analytics' AND state='ready'",[textField($input,'analysis_job_id',32,true),$c['id'],$_SESSION['user_id']]);if(!$job)fail('Сохранённый AI-анализ недоступен',404);$saved=decode($job['result_json']);$snapshot=$saved['snapshot'];$insights=$saved['insights'];if($snapshot['period']['from']!==$period['from']||$snapshot['period']['to']!==$period['to'])fail('Период AI-снимка отличается от экспорта',409);}else $snapshot=analyticsSnapshot($c,$input);$sheets=[...$sheets,...exportStatisticsSheets($snapshot,$insights)];
