  }
 }
 $bytes=xlsxWorkbook($sheets,$illustration);audit('excel_exported',['kind'=>$kind,'sheets'=>count($sheets)]);return ['bytes'=>$bytes,'filename'=>'EASY3-'.$kind.'-'.date('Ymd').'.xlsx'];
}
